import {initialRepairs,repairReasons,technicians} from './repairs.mjs';
const when=v=>v.replace('T',' · ');
const tech=id=>technicians.find(t=>t.id===id)?.name||id;
export function technicianHome(s,safe){
 const pending=s.repairOrders.filter(r=>r.confirmation==='Pending').length;
 const critical=s.issueCases.filter(i=>i.severity==='Emergency'&&i.status!=='Resolved');
 return `${critical.length?`<section class="emergency-banner" role="status"><b>${critical.length} emergency ${critical.length===1?'issue requires':'issues require'} attention</b>${critical.map(i=>`<button class="btn" data-repair="${i.repairId}">${safe(s.repairOrders.find(r=>r.id===i.repairId).client)} · ${safe(i.title)}</button>`).join('')}</section>`:''}<section class="technician-hero"><div class="hero-copy"><div class="eyebrow">BUILT AROUND THE PERSON DOING THE WORK</div><h2>Your repair day,<br>connected.</h2><p>Know the job. Keep the appointment. When plans change, keep the whole story.</p><div class="actions"><button class="btn primary" data-nav="Repairs">Open repair schedule ↗</button><button class="btn" data-nav="Workflows">Follow the work</button></div><div class="hero-stats"><div><b>${s.repairOrders.length}</b><span>scheduled repair visits</span></div><div><b>${pending||'All confirmed'}</b><span>${pending?'awaiting client confirmation':'appointment status'}</span></div><div><b>${s.repairHistory.length||'Original slots'}</b><span>${s.repairHistory.length?'recorded appointment changes':'no changes recorded yet'}</span></div></div></div><figure><img src="assets/technician-repair.jpg" alt="Technician inspecting an electrical appliance at a repair workbench" width="422" height="750"><figcaption>Repair-work photography · Bulat843 / Pexels</figcaption></figure></section><div class="repair-home-grid"><section class="card"><div class="card-head"><div><h2>Upcoming repair visits</h2><p>Toronto local time · simulated service orders</p></div></div><div class="repair-visits">${s.repairOrders.slice().sort((a,b)=>a.scheduledAt.localeCompare(b.scheduledAt)).map(r=>`<button class="repair-visit" data-repair="${r.id}"><span class="visit-date">${safe(when(r.scheduledAt))}</span><span><b>${safe(r.product)}</b><small>${safe(r.client)} · ${safe(tech(r.technician))}</small><small>${safe(r.issue)}</small></span><span class="badge ${r.confirmation==='Pending'?'amber':'green'}">${r.confirmation}</span></button>`).join('')}</div></section><section class="card repair-story"><img src="assets/technician-diagnostics.jpg" alt="Service technician working on an electrical control panel" width="1000" height="750" loading="lazy"><div class="panel-body"><h2>A change of plans should never erase the plan.</h2><p>Client requests, parts delays or access issues: record why a visit moved, who requested it, and the appointment it replaced.</p><button class="btn" data-nav="Repairs">Review appointment history</button><small class="photo-credit">Photography · ranjeet / Pexels</small></div></section></div>`;
}
export function repairsView(s,safe,selectedRepair){
 const order=s.repairOrders.find(r=>r.id===selectedRepair)||s.repairOrders[0],baseline=initialRepairs().repairOrders.find(r=>r.id===order.id),history=s.repairHistory.filter(e=>e.repairId===order.id);
 const counts=repairReasons.map(reason=>({reason,count:s.repairHistory.filter(e=>e.reason===reason).length})).filter(r=>r.count);
 return `<div class="operator-context">Recording as <b>${safe(s.operatorName)}</b> · <button class="text-link" data-nav="Workflows">Change demo operator</button><span>Appointments: America/Toronto · event timestamps: UTC</span></div><div class="workflow-grid"><section class="card"><div class="card-head"><h2>Repair orders</h2><span class="badge gray">${s.repairOrders.length} appointments</span></div><div class="work-list">${s.repairOrders.map(r=>`<button class="work-item ${r.id===order.id?'selected':''}" data-repair="${r.id}"><span><b>${safe(r.product)}</b><small>${r.id} · ${safe(r.client)}</small><small>${safe(when(r.scheduledAt))} · ${safe(tech(r.technician))}</small></span><span class="badge ${r.confirmation==='Pending'?'amber':'green'}">${r.confirmation}</span></button>`).join('')}</div><div class="panel-body"><h3>Reasons recorded across repair orders</h3>${counts.length?counts.map(r=>`<div class="metric-row"><span>${safe(r.reason)}</span><b>${r.count}</b></div>`).join(''):'<p class="definition">No rescheduling requests recorded yet. Original appointments are shown for every order.</p>'}</div></section><section class="card"><div class="card-head"><div><h2>${safe(order.product)} · ${order.id}</h2><p>${safe(order.client)} · ${safe(order.issue)}</p></div></div><div class="panel-body"><div class="appointment-summary"><div><small>Original appointment</small><b>${safe(when(baseline.scheduledAt))}</b><span>${safe(tech(baseline.technician))}</span></div><div><small>Current appointment</small><b>${safe(when(order.scheduledAt))}</b><span>${safe(tech(order.technician))} · ${order.durationMinutes} minutes</span></div></div><p class="confirmation-note">Client confirmation: <b>${order.confirmation}</b></p><form id="reschedule-form"><label for="repair-date">Revised appointment · Toronto time</label><input type="datetime-local" id="repair-date" name="scheduledAt" value="${order.scheduledAt}" required><label for="repair-technician">Technician</label><select id="repair-technician" name="technician">${technicians.map(t=>`<option value="${t.id}" ${t.id===order.technician?'selected':''}>${safe(t.name)}</option>`).join('')}</select><label for="repair-requested-by">Who requested the change?</label><select id="repair-requested-by" name="requestedBy">${['Client','Technician','Dispatcher'].map(r=>`<option>${r}</option>`).join('')}</select><label for="repair-reason">Reason for rescheduling</label><select id="repair-reason" name="reason" required><option value="">Choose a reason…</option>${repairReasons.map(r=>`<option>${r}</option>`).join('')}</select><label for="repair-note">Request details and follow-up</label><textarea id="repair-note" name="note" maxlength="1000" required placeholder="What changed, why, and what the client agreed to."></textarea><label class="confirmation-check"><input type="checkbox" name="confirmed"> Client confirmed the revised appointment</label><p class="definition">Unchecked changes stay pending confirmation. This records what the operator reports; it does not contact the client. Conflicting repair slots are blocked. Ambiguous or nonexistent daylight-saving times are rejected.</p><button class="btn primary" type="submit">Record reschedule & keep previous appointment</button></form><h3 class="history-title">Appointment history · ${history.length+1} records</h3><ol class="workflow-timeline"><li class="workflow-event"><b>Original appointment</b><p>${safe(when(baseline.scheduledAt))} · ${safe(tech(baseline.technician))}</p><p class="definition">Simulated starting booking; no earlier client conversation is claimed.</p></li>${history.map(e=>`<li class="workflow-event"><div class="risk-line"><b>${safe(e.reason)}</b><small>${safe(new Date(e.time).toLocaleString('en-US',{timeZone:'UTC'}))} UTC</small></div><p class="event-actor">Requested by ${safe(e.requestedBy)} · Recorded by ${safe(e.actor)}</p><dl class="step-diff"><div><dt>Appointment</dt><dd>${safe(when(e.before.scheduledAt))} → ${safe(when(e.after.scheduledAt))}</dd></div><div><dt>Technician</dt><dd>${safe(tech(e.before.technician))} → ${safe(tech(e.after.technician))}</dd></div><div><dt>Confirmation</dt><dd>${e.before.confirmation} → ${e.after.confirmation}</dd></div></dl><p>${safe(e.note)}</p></li>`).join('')}</ol><p class="definition">History is saved in this browser and included in JSON backups and workflow CSV. The fictional repair schedule is separate from the earlier staffing/recording simulation. Travel time, parts stock, working hours, real client messages and shared-user access are not integrated.</p></div></section></div>`;
}
